import 'package:flutter/material.dart';

class TafzoretLogo {
  final String id; // ייחודי בתוך העולם, למשל 'w3_17'
  final String answer;
  final String imagePath;
  final Color logoColor;
  final List<String> keyboard;
  final String? ansEn;
  final List<String>? keyboardEn;

  const TafzoretLogo({
    required this.id,
    required this.answer,
    required this.imagePath,
    required this.logoColor,
    required this.keyboard,
    this.ansEn,
    this.keyboardEn,
  });

  String answerFor(bool hebrew) => (hebrew || ansEn == null) ? answer : ansEn!;
  List<String> keyboardFor(bool hebrew) =>
      (hebrew || keyboardEn == null) ? keyboard : keyboardEn!;
}

